/**
 * Job Responds
 * ------------
 * Job answers the Lord: I had heard of you by the hearing of the ear, but now my eye sees you; therefore I repent in dust and ashes. Stage: a man kneeling as the storm breaks, his hand over his mouth, the whirlwind withdrawing; the first rain in years; a quiet, broken peace.
 *
 * Palette 0x241a10 → 0x060402 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./job-kit.js.
 */

import { THREE, createScene, rain, pillar, person } from './job-kit.js';

const BG = 0x241a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2367817676, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* storm: rain sheets across the whole frame */
    rain(W, group, 900, 230, 65, 16);

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x2f2215, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x241a10, bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: 0.22, s: 1.05 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: -0.47, s: 1.18 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: -0.33, s: 1.16 });

    return W.finish();
}

export default { build };
